html:
{%- set d = get_profitability_data(doc.name) -%}
{%- set m = d.quotation_meta -%}
{%- set t = d.totals -%}
{%- set cur = m.currency -%}

<style>
* { box-sizing:border-box; margin:0; padding:0; }
body { font-family:Arial,Helvetica,sans-serif; font-size:9pt; color:#222; }
@page { margin:1.5cm; }
.hdr { border-bottom:3px solid #1a1a2e; padding-bottom:10px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:flex-start; }
.hdr h1 { font-size:13pt; color:#1a1a2e; font-weight:bold; }
.badge { background:#c00; color:#fff; font-size:7pt; font-weight:bold; letter-spacing:2px; text-transform:uppercase; padding:4px 10px; border-radius:2px; }
.meta { display:grid; grid-template-columns:repeat(4,1fr); gap:8px; background:#f8f9fc; border:1px solid #e0e4ee; padding:10px 12px; margin-bottom:14px; font-size:8pt; }
.ml { color:#999; font-weight:bold; text-transform:uppercase; font-size:7pt; }
.mv { font-weight:bold; color:#1a1a2e; margin-top:2px; font-size:9pt; }
h2 { font-size:9.5pt; font-weight:bold; color:#fff; background:#1a1a2e; padding:5px 10px; margin:14px 0 6px; }
table { width:100%; border-collapse:collapse; font-size:8pt; margin-bottom:6px; }
th { background:#e8edf8; color:#1a1a2e; padding:5px 8px; text-align:left; border-bottom:1px solid #bbc; font-weight:bold; }
th.r, td.r { text-align:right; }
td { padding:4px 8px; border-bottom:1px solid #eee; vertical-align:top; }
tr.ph td { background:#f0f4ff; font-weight:bold; border-top:2px solid #1a1a2e; padding:5px 8px; }
tr.sub td { background:#f4f6fb; font-style:italic; border-top:1px solid #ccd; }
tr.tf td { background:#1a1a2e; color:#fff; font-weight:bold; padding:6px 8px; }
.tw { display:flex; justify-content:flex-end; margin-bottom:14px; }
.ti { width:44%; }
.tr { display:flex; justify-content:space-between; padding:3px 8px; font-size:8.5pt; border-bottom:1px solid #f0f0f0; }
.tg { background:#1a1a2e; color:#fff; font-weight:bold; font-size:11pt; padding:7px 8px; margin-top:4px; }
.qc { width:100%; border-collapse:collapse; font-size:8pt; }
.qc td { padding:4px 8px; border-bottom:1px solid #eee; }
.ok { color:#1a7a1a; font-weight:bold; }
.wa { color:#b85c00; font-weight:bold; }
.wb { background:#fff8e6; border:1px solid #f0c060; padding:8px 12px; margin-bottom:10px; font-size:8pt; }
.wb ul { padding-left:16px; color:#7a4000; }
.sg { display:grid; grid-template-columns:repeat(3,1fr); gap:24px; margin-top:18px; }
.st { font-size:8pt; font-weight:bold; color:#1a1a2e; border-bottom:1px solid #1a1a2e; padding-bottom:3px; margin-bottom:6px; }
.sl { border-bottom:1px solid #555; height:36px; margin:16px 0 5px; }
.sl2 { font-size:7.5pt; color:#666; }
.ft { margin-top:18px; border-top:1px solid #ddd; padding-top:6px; font-size:7pt; color:#aaa; display:flex; justify-content:space-between; }
</style>

<div>
<div class="hdr">
<div><h1>Rentabilidad Estimada de Propuesta</h1><div style="font-size:8pt;color:#555;margin-top:3px">{{ m.proposal_title }}</div></div>
<div class="badge">Uso Interno Confidencial</div>
</div>
<div class="meta">
<div><div class="ml">Cliente</div><div class="mv">{{ m.customer_name }}</div></div>
<div><div class="ml">Folio</div><div class="mv">{{ m.name }}</div></div>
<div><div class="ml">Fecha</div><div class="mv">{{ frappe.utils.formatdate(m.transaction_date) }}</div></div>
<div><div class="ml">Moneda</div><div class="mv">{{ cur }}</div></div>
<div><div class="ml">Elaboro</div><div class="mv">{{ m.elaborated_by or '—' }}</div></div>
<div><div class="ml">Generado</div><div class="mv">{{ frappe.utils.now_datetime().strftime('%d/%m/%Y %H:%M') }}</div></div>
<div><div class="ml">Venta neta</div><div class="mv">{{ '{:,.0f}'.format(t.net_total) }} {{ cur }}</div></div>
<div><div class="ml">Margen</div><div class="mv">{{ '{:.1f}'.format(t.margin_pct) }}%</div></div>
</div>

<h2>Costo Laboral</h2>
<table>
<thead><tr><th>Fase / Actividad</th><th style="width:13%">Actividad</th><th class="r" style="width:8%">Horas</th><th class="r" style="width:10%">$/hora</th><th class="r" style="width:11%">Costo</th><th style="width:14%">Nota</th></tr></thead>
<tbody>
{%- set cp = namespace(v='__NONE__', ph=0.0, pc=0.0) -%}
{%- for row in d.labor_rows -%}
{%- if row.phase != cp.v -%}
{%- if cp.v != '__NONE__' -%}
<tr class="sub"><td colspan="4" class="r"><em>Total {{ cp.v }}</em></td><td class="r"><em>{{ '{:g}'.format(cp.ph) }}h / {{ '{:,.0f}'.format(cp.pc) }}</em></td><td></td></tr>
{%- endif -%}
{%- set cp.v = row.phase -%}
{%- set cp.ph = 0.0 -%}
{%- set cp.pc = 0.0 -%}
{%- if row.phase -%}<tr class="ph"><td colspan="6">{{ row.phase }}</td></tr>{%- endif -%}
{%- endif -%}
{%- set cp.ph = cp.ph + row.hours -%}
{%- set cp.pc = cp.pc + row.cost -%}
<tr><td style="padding-left:16px">{{ row.title }}</td><td>{{ row.activity_type }}</td><td class="r">{{ '{:g}'.format(row.hours) if row.hours else '' }}</td><td class="r">{{ '{:,.0f}'.format(row.costing_rate) if row.costing_rate else '' }}</td><td class="r">{{ '{:,.0f}'.format(row.cost) if row.cost else '' }}</td><td style="color:#b85c00">{{ 'Sin activity_type' if row.notes == 'sin_activity_type' else ('Sin costing_rate' if row.notes == 'sin_costing_rate' else '') }}</td></tr>
{%- endfor -%}
{%- if cp.v != '__NONE__' -%}
<tr class="sub"><td colspan="4" class="r"><em>Total {{ cp.v }}</em></td><td class="r"><em>{{ '{:g}'.format(cp.ph) }}h / {{ '{:,.0f}'.format(cp.pc) }}</em></td><td></td></tr>
{%- endif -%}
</tbody>
<tfoot><tr class="tf"><td colspan="2">Total costo laboral</td><td class="r">{{ '{:g}'.format(t.labor_hours) }}h</td><td></td><td class="r">{{ '{:,.0f}'.format(t.labor_cost) }} {{ cur }}</td><td></td></tr></tfoot>
</table>

<h2>Items Comprados / Revendidos</h2>
<table>
<thead><tr><th>Item</th><th class="r" style="width:8%">Cant.</th><th class="r" style="width:13%">Costo/unit</th><th class="r" style="width:13%">Costo total</th><th style="width:18%">Fuente</th></tr></thead>
<tbody>
{%- for row in d.item_cost_rows -%}
{%- if not row.covered_by_scope -%}
<tr><td>{{ row.item_name }}</td><td class="r">{{ '{:g}'.format(row.qty) }}</td><td class="r">{{ '{:,.0f}'.format(row.cost_per_unit) if row.source != 'sin_costo' else '' }}</td><td class="r">{{ '{:,.0f}'.format(row.total_cost) if row.source != 'sin_costo' else '' }}</td><td style="font-size:7.5pt">{{ 'Sin costo estimable' if row.source == 'sin_costo' else row.source }}</td></tr>
{%- endif -%}
{%- endfor -%}
</tbody>
<tfoot><tr class="tf"><td colspan="3">Total costo items</td><td class="r">{{ '{:,.0f}'.format(t.item_cost) }} {{ cur }}</td><td></td></tr></tfoot>
</table>

<h2>Resumen de Rentabilidad</h2>
<div class="tw"><div class="ti">
<div class="tr"><span>Venta neta</span><span>{{ '{:,.2f}'.format(t.net_total) }} {{ cur }}</span></div>
<div class="tr"><span>Costo laboral</span><span>{{ '{:,.2f}'.format(t.labor_cost) }} {{ cur }}</span></div>
<div class="tr"><span>Costo items</span><span>{{ '{:,.2f}'.format(t.item_cost) }} {{ cur }}</span></div>
<div class="tr" style="font-weight:bold;border-top:1px solid #bbb"><span>Costo total</span><span>{{ '{:,.2f}'.format(t.total_cost) }} {{ cur }}</span></div>
<div class="tr tg"><span>Margen estimado</span><span>{{ '{:,.2f}'.format(t.margin) }} {{ cur }} ({{ '{:.1f}'.format(t.margin_pct) }}%)</span></div>
</div></div>

<h2>Validaciones Q/C</h2>
<table class="qc">
{%- for chk in d.qc_checks -%}
<tr><td style="width:8%" class="{{ 'ok' if chk.status == 'ok' else 'wa' }}">{{ 'OK' if chk.status == 'ok' else 'Advertencia' }}</td><td>{{ chk.label }}</td><td style="width:20%;color:#666;font-size:7.5pt">{{ chk.detail }}</td></tr>
{%- endfor -%}
</table>

{%- if d.warnings -%}
<div class="wb" style="margin-top:10px"><strong style="color:#b85c00">Advertencias:</strong><ul>{%- for w in d.warnings -%}<li>{{ w }}</li>{%- endfor -%}</ul></div>
{%- endif -%}

<h2>Elaboracion y Aprobacion</h2>
<p style="font-size:8pt;color:#555;margin-bottom:12px">Aprobacion interna antes de enviar al cliente. Flujo digital: Prioridad 3 pendiente.</p>
<div class="sg">
<div><div class="st">Elaboro</div><div style="font-size:8.5pt;font-weight:bold;margin-top:6px">{{ m.elaborated_by or '—' }}</div><div class="sl"></div><div class="sl2">Cargo: ______________________</div><div class="sl2">Fecha: ______________________</div></div>
<div><div class="st">Reviso</div><div class="sl"></div><div class="sl2">Nombre: ______________________</div><div class="sl2">Cargo: ______________________</div><div class="sl2">Fecha: ______________________</div></div>
<div><div class="st">Aprobo</div><div class="sl"></div><div class="sl2">Nombre: ______________________</div><div class="sl2">Cargo: ______________________</div><div class="sl2">Fecha: ______________________</div></div>
</div>
<div class="ft"><span>Rentabilidad Estimada — erpnext_proposals</span><span>{{ frappe.utils.now_datetime().strftime('%d/%m/%Y %H:%M') }}</span></div>
</div>
